import re, datetime

def parse_auditd():
    with open('/app/logs/auditd.log') as f:
        content = f.read()

    # split by msg=audit(epoch:seq)
    events = re.findall(r'msg=audit\((\d+\.\d+):(\d+)\): (.*)', content)

    records = {}
    for ts_str, seq, rest in events:
        ts = float(ts_str)
        dt = datetime.datetime.fromtimestamp(ts, tz=datetime.timezone.utc).strftime('%Y-%m-%d %H:%M:%S')
        if seq not in records:
            records[seq] = {'ts': dt, 'items': []}
        records[seq]['items'].append(rest)

    for seq, data in records.items():
        print(f\"{data['ts']} | SEQ:{seq} | {' || '.join(data['items'])}\")

parse_auditd()
